members.products.graphql:
extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key"])

type Query {
  topProducts: [Product!]
}

type Product @key(fields: "id") {
  id: ID!
  priceCents: Int!
}

members.reviews.graphql:
extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key", "@requires"])

type Query {
  latestReviews: [String!]
}

type Product @key(fields: "id") {
  id: ID!
  valueScore: Float @requires(fields: "warehouseCode")
}
